  f_heart: { en: "Heart", si: "හෘදය", ta: "இதயம்" },
  f_surgery: { en: "Surgery", si: "සැත්කම්", ta: "அறுவை சிகிச்சை" },
  f_blood: { en: "Blood", si: "රුධිරය", ta: "இரத்தம்" },
  f_organ: { en: "Organ pledge", si: "අවයව පොරොන්දුව", ta: "உறுப்பு உறுதிமொழி" },
  f_urgent_resp: { en: "⚡ Urgent responders", si: "⚡ කඩිනම් සහායකයින්", ta: "⚡ அவசர பதிலளிப்பவர்கள்" },
  f_available: { en: "Available now", si: "දැන් ලබා ගත හැක", ta: "இப்போது கிடைக்கும்" },
  blood_donor_lbl: { en: "Blood donor", si: "රුධිර දායක", ta: "இரத்த தானம்" },
  no_patients: { en: "No patients match your search.", si: "ඔබේ සෙවුමට ගැළපෙන රෝගීන් නැත.", ta: "உங்கள் தேடலுக்குப் பொருந்தும் நோயாளிகள் இல்லை." },
