  foot_about: { en: "A verified medical fundraising platform. Every rupee is tracked, receipted and audited.", si: "තහවුරු කළ රෝගීන් සඳහා වෛද්‍ය අරමුදල් රැස් කරන වේදිකාවක්. හැම රුපියලක්ම සටහන් කරලා, රිසිට්පත් දීලා, පරීක්ෂා කරනවා.", ta: "சரிபார்க்கப்பட்ட மருத்துவ நிதி திரட்டும் தளம். ஒவ்வொரு ரூபாயும் கண்காணிக்கப்பட்டு, ரசீது வழங்கப்பட்டு, தணிக்கை செய்யப்படுகிறது." },
  foot_stories: { en: "Success stories", si: "සාර්ථක කතා", ta: "வெற்றிக் கதைகள்" },
  foot_blood: { en: "Blood donors", si: "රුධිර දායකයින්", ta: "இரத்த தானம் செய்பவர்கள்" },
  foot_fraud: { en: "Report fraud", si: "වංචාවක් වාර්තා කරන්න", ta: "மோசடியைப் புகாரளி" },
